import { axialToPixel } from "./hex.ts";
import {
  createTopologyViewportController,
  type TopologyCameraState,
  type TopologyWorldBounds,
  type TopologyViewportController,
} from "./TopologyViewportController.ts";
import type { RelationshipContext } from "./relationshipContext.ts";
import type { TopologyCameraPersistence } from "./sceneConfig.ts";
import { createCameraWorldSignature } from "./cameraMath.ts";
import {
  ensureDeveloperSceneId,
  registerDeveloperCamera,
} from "./DeveloperRegistry.ts";

export interface SceneNavigationNode {
  id: string;
  q: number;
  r: number;
}

export interface SceneNavigationControllerOptions {
  shell: HTMLElement;
  scene: HTMLElement;
  nodes: SceneNavigationNode[];
  worldRadius: number;
  worldBounds: TopologyWorldBounds;
  zoomStep: number;
  keyboardPanStep?: number;
  edgePanThreshold?: number;
  edgePanSpeed?: number;
  cameraPersistence?: TopologyCameraPersistence;
  transitionDuration: number;
  safeAreaRatio?: number;
  selectedId?: string;
  initialCamera?: Partial<TopologyCameraState>;
  fitOnInit?: boolean;
  interactiveMiniMap?: boolean;
  enableSceneGestures?: boolean;
  enableSceneWheel?: boolean;
  resizeTargets?: HTMLElement[];
  onMiniMapNodeSelect?: (entityId: string) => void;
  onReady?: () => void;
}

export interface SceneNavigationController {
  viewport: TopologyViewportController;
  getSelectedId(): string;
  select(entityId: string): void;
  syncRelationshipContext(context: RelationshipContext): void;
  setTopology(nodes: SceneNavigationNode[], bounds?: TopologyWorldBounds): void;
  ensureVisible(entityId: string, animated?: boolean): boolean;
  centerOnSelection(animated?: boolean): void;
  resetCamera(animated?: boolean): void;
  destroy(): void;
}

export function createSceneNavigationController({
  shell,
  scene,
  nodes,
  worldRadius,
  worldBounds,
  zoomStep,
  keyboardPanStep = 72,
  edgePanThreshold = 52,
  edgePanSpeed = 360,
  cameraPersistence = "none",
  transitionDuration,
  safeAreaRatio = 0.16,
  selectedId = "",
  initialCamera = {},
  fitOnInit = true,
  interactiveMiniMap = true,
  enableSceneGestures = true,
  enableSceneWheel = true,
  resizeTargets = [shell, scene],
  onMiniMapNodeSelect,
  onReady,
}: SceneNavigationControllerOptions): SceneNavigationController {
  const sceneGrid = scene.querySelector<SVGSVGElement>(".topology-grid");
  const miniMap = shell.querySelector<SVGSVGElement>("[data-topology-mini-map]");
  const miniFrame = shell.querySelector<SVGRectElement>("[data-topology-mini-map-frame]");
  const miniReadout = shell.querySelector<HTMLElement>("[data-topology-mini-map-readout]");
  const miniNodes = Array.from(shell.querySelectorAll<SVGElement>("[data-topology-mini-node-id]"));
  const cameraButtons = Array.from(shell.querySelectorAll<HTMLButtonElement>("[data-topology-mini-map-action]"));
  const splitLayout = shell.closest<HTMLElement>("[data-topology-split]");
  const sheetContent = splitLayout?.querySelector<HTMLElement>("[data-topology-split-content]") ?? null;
  const mobileSheetMedia = window.matchMedia("(max-width: 980px)");
  let nodeMap = new Map(nodes.map((node) => [node.id, node]));
  const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  const cleanups: Array<() => void> = [];
  let activeId = selectedId;
  const previousSceneRole = scene.getAttribute("role");
  const previousSceneLabel = scene.getAttribute("aria-label");
  const previousSceneTabIndex = scene.getAttribute("tabindex");

  scene.setAttribute("role", "region");
  scene.setAttribute("aria-label", "Topology camera. Use arrow keys to pan when the map canvas is focused.");
  scene.setAttribute("tabindex", "0");
  cleanups.push(() => {
    if (previousSceneRole === null) scene.removeAttribute("role");
    else scene.setAttribute("role", previousSceneRole);
    if (previousSceneLabel === null) scene.removeAttribute("aria-label");
    else scene.setAttribute("aria-label", previousSceneLabel);
    if (previousSceneTabIndex === null) scene.removeAttribute("tabindex");
    else scene.setAttribute("tabindex", previousSceneTabIndex);
  });

  function pixelToAxialContinuous(point: { x: number; y: number }) {
    const r = (2 * point.y) / (3 * worldRadius);
    const q = point.x / (Math.sqrt(3) * worldRadius) - r / 2;
    return { q, r };
  }

  interface PersistedCameraState {
    version: 1;
    worldSignature: string;
    center: { q: number; r: number };
    zoom: number;
    savedAt: number;
  }

  const worldSignature = createCameraWorldSignature({
    radius: worldRadius,
    bounds: worldBounds,
    nodes,
  });
  const cameraStorageKey = `otf:camera:${window.location.pathname}`;
  let cameraStorage: Storage | null = null;
  let cameraPersistenceTimer = 0;
  let pendingCameraState: TopologyCameraState | null = null;

  try {
    cameraStorage = cameraPersistence === "session"
      ? window.sessionStorage
      : cameraPersistence === "local"
        ? window.localStorage
        : null;
  } catch {
    cameraStorage = null;
  }

  function removePersistedCamera() {
    if (cameraPersistenceTimer) window.clearTimeout(cameraPersistenceTimer);
    cameraPersistenceTimer = 0;
    pendingCameraState = null;
    try {
      cameraStorage?.removeItem(cameraStorageKey);
    } catch {
      // Storage may become unavailable in privacy-constrained browsers.
    }
  }

  function readPersistedCamera() {
    if (!cameraStorage) return null;

    try {
      const raw = cameraStorage.getItem(cameraStorageKey);
      if (!raw) return null;
      const stored = JSON.parse(raw) as Partial<PersistedCameraState>;
      const isCompatible = stored.version === 1
        && stored.worldSignature === worldSignature
        && Number.isFinite(stored.center?.q)
        && Number.isFinite(stored.center?.r)
        && Number.isFinite(stored.zoom)
        && Number(stored.zoom) > 0;

      if (!isCompatible) {
        cameraStorage.removeItem(cameraStorageKey);
        return null;
      }

      return {
        center: { q: Number(stored.center?.q), r: Number(stored.center?.r) },
        zoom: Number(stored.zoom),
      };
    } catch {
      removePersistedCamera();
      return null;
    }
  }

  function flushCameraPersistence() {
    if (cameraPersistenceTimer) window.clearTimeout(cameraPersistenceTimer);
    cameraPersistenceTimer = 0;
    if (!cameraStorage || !pendingCameraState) return;
    const camera = pendingCameraState;
    pendingCameraState = null;

    try {
      const stored: PersistedCameraState = {
        version: 1,
        worldSignature,
        center: { ...camera.center },
        zoom: camera.zoom,
        savedAt: Date.now(),
      };
      cameraStorage.setItem(cameraStorageKey, JSON.stringify(stored));
    } catch {
      cameraStorage = null;
    }
  }

  function scheduleCameraPersistence(camera: TopologyCameraState) {
    if (!cameraStorage) return;
    pendingCameraState = camera;
    if (cameraPersistenceTimer) window.clearTimeout(cameraPersistenceTimer);
    cameraPersistenceTimer = window.setTimeout(flushCameraPersistence, 120);
  }

  const restoredCamera = readPersistedCamera();
  cleanups.push(flushCameraPersistence);

  function getViewportInsets() {
    if (!sceneGrid || !sheetContent || !mobileSheetMedia.matches) return {};
    if (splitLayout?.getAttribute("data-topology-split-state") === "full") return {};

    const sceneRect = sceneGrid.getBoundingClientRect();
    const sheetRect = sheetContent.getBoundingClientRect();
    const horizontalOverlap = Math.min(sceneRect.right, sheetRect.right) - Math.max(sceneRect.left, sheetRect.left);
    const sheetCoversSceneBottom = sheetRect.top < sceneRect.bottom && sheetRect.bottom >= sceneRect.bottom;
    if (horizontalOverlap <= 0 || !sheetCoversSceneBottom) return {};

    return {
      bottom: Math.min(sceneRect.height, Math.max(0, sceneRect.bottom - Math.max(sceneRect.top, sheetRect.top))),
    };
  }

  const viewport = createTopologyViewportController({
    root: shell,
    sceneGrid,
    miniFrame,
    miniReadout,
    miniNodes,
    worldRadius,
    worldBounds,
    topologyNodes: nodes,
    cameraTransitionDuration: transitionDuration,
    safeAreaRatio,
    getViewportInsets,
    initialCamera: {
      center: restoredCamera?.center ?? initialCamera.center ?? { q: 0, r: 0 },
      zoom: restoredCamera?.zoom ?? initialCamera.zoom ?? 1,
      viewportWidth: (restoredCamera ? shell.clientWidth : initialCamera.viewportWidth ?? shell.clientWidth) || 1,
      viewportHeight: (restoredCamera ? shell.clientHeight : initialCamera.viewportHeight ?? shell.clientHeight) || 1,
    },
    onCameraChange: scheduleCameraPersistence,
  });

  if (splitLayout) {
    const handleSheetStateChange = (event: Event) => {
      const detail = (event as CustomEvent<{ state?: string; settled?: boolean }>).detail;
      if (!detail?.settled || detail.state === "full" || !activeId) return;
      viewport.ensureVisible(activeId, !reducedMotion);
    };
    splitLayout.addEventListener("topology:sheet-statechange", handleSheetStateChange);
    cleanups.push(() => splitLayout.removeEventListener("topology:sheet-statechange", handleSheetStateChange));
  }

  function select(entityId: string) {
    activeId = entityId;
    viewport.syncSelection(entityId);
  }

  function setTopology(nextNodes: SceneNavigationNode[], bounds?: TopologyWorldBounds) {
    nodeMap = new Map(nextNodes.map((node) => [node.id, node]));
    viewport.setTopology(nextNodes, bounds);
  }

  function syncRelationshipContext(context: RelationshipContext) {
    viewport.syncRelationshipContext(context);
  }

  function ensureVisible(entityId: string, animated = true) {
    return viewport.ensureVisible(entityId, animated && !reducedMotion);
  }

  function centerOnSelection(animated = true) {
    const node = nodeMap.get(activeId);
    if (node) viewport.centerOnNode(node, animated && !reducedMotion);
  }

  function resetCamera(animated = true) {
    removePersistedCamera();
    const shouldAnimate = animated && !reducedMotion;
    if (fitOnInit) {
      viewport.fit(shouldAnimate);
      return;
    }

    const current = viewport.getCamera();
    const target = {
      center: initialCamera.center ?? { q: 0, r: 0 },
      zoom: initialCamera.zoom ?? 1,
      viewportWidth: current.viewportWidth,
      viewportHeight: current.viewportHeight,
    };
    if (shouldAnimate) viewport.animateCameraTo(target);
    else viewport.applyCamera(target);
  }

  for (const button of cameraButtons) {
    const handleClick = () => {
      const action = button.getAttribute("data-topology-mini-map-action");
      if (action === "zoom-in") viewport.zoomBy(zoomStep);
      if (action === "zoom-out") viewport.zoomBy(-zoomStep);
      if (action === "fit") {
        removePersistedCamera();
        viewport.fit(!reducedMotion);
      }
      if (action === "center") centerOnSelection(true);
    };

    button.addEventListener("click", handleClick);
    cleanups.push(() => button.removeEventListener("click", handleClick));
  }

  if (sceneGrid && enableSceneGestures) {
    const pointers = new Map<number, { x: number; y: number }>();
    let startCenter: { x: number; y: number } | null = null;
    let startPoint: { x: number; y: number } | null = null;
    let startCentroid: { x: number; y: number } | null = null;
    let startDistance = 0;
    let startZoom = 1;
    let suppressClick = false;
    let edgePanRaf = 0;
    let edgePanPreviousTime = 0;
    let edgePanOffset = { x: 0, y: 0 };
    let gestureRect: DOMRect | null = null;

    const getCentroid = () => {
      const points = Array.from(pointers.values());
      if (!points.length) return null;
      return {
        x: points.reduce((sum, point) => sum + point.x, 0) / points.length,
        y: points.reduce((sum, point) => sum + point.y, 0) / points.length,
      };
    };
    const getDistance = () => {
      const points = Array.from(pointers.values());
      return points.length < 2 ? 0 : Math.hypot(points[0].x - points[1].x, points[0].y - points[1].y);
    };
    const resetFromCamera = () => {
      const camera = viewport.getCamera();
      startCenter = axialToPixel(camera.center, worldRadius);
      startZoom = camera.zoom;
    };
    const stopEdgePan = () => {
      if (edgePanRaf) window.cancelAnimationFrame(edgePanRaf);
      edgePanRaf = 0;
      edgePanPreviousTime = 0;
    };
    const getEdgeVelocity = (point: { x: number; y: number }) => {
      if (!gestureRect) return { x: 0, y: 0 };
      const threshold = Math.max(16, edgePanThreshold);
      const leftDistance = point.x - gestureRect.left;
      const rightDistance = gestureRect.right - point.x;
      const topDistance = point.y - gestureRect.top;
      const bottomDistance = gestureRect.bottom - point.y;
      const axisVelocity = (leading: number, trailing: number) => leading < threshold
        ? -edgePanSpeed * (1 - Math.max(0, leading) / threshold)
        : trailing < threshold
          ? edgePanSpeed * (1 - Math.max(0, trailing) / threshold)
          : 0;

      return {
        x: axisVelocity(leftDistance, rightDistance),
        y: axisVelocity(topDistance, bottomDistance),
      };
    };
    const applySinglePointerCamera = () => {
      const point = pointers.values().next().value;
      if (!point || !startPoint || !startCenter) return;
      const dx = point.x - startPoint.x;
      const dy = point.y - startPoint.y;
      const zoom = Math.max(startZoom, 0.0001);
      sceneGrid.classList.add("is-gesture-active");
      viewport.applyCamera({
        center: pixelToAxialContinuous({
          x: startCenter.x - dx / zoom + edgePanOffset.x / zoom,
          y: startCenter.y - dy / zoom + edgePanOffset.y / zoom,
        }),
        zoom: startZoom,
        viewportWidth: viewport.getCamera().viewportWidth,
        viewportHeight: viewport.getCamera().viewportHeight,
      });
    };
    const runEdgePan = (now: number) => {
      edgePanRaf = 0;
      const point = pointers.values().next().value;
      if (!point || pointers.size !== 1 || !suppressClick) {
        edgePanPreviousTime = 0;
        return;
      }

      const velocity = getEdgeVelocity(point);
      if (!velocity.x && !velocity.y) {
        edgePanPreviousTime = 0;
        return;
      }

      const elapsed = edgePanPreviousTime ? Math.min(32, now - edgePanPreviousTime) / 1000 : 0;
      edgePanPreviousTime = now;
      edgePanOffset.x -= velocity.x * elapsed;
      edgePanOffset.y -= velocity.y * elapsed;
      applySinglePointerCamera();
      edgePanRaf = window.requestAnimationFrame(runEdgePan);
    };
    const scheduleEdgePan = () => {
      if (!edgePanRaf) edgePanRaf = window.requestAnimationFrame(runEdgePan);
    };
    const handlePointerDown = (event: PointerEvent) => {
      const target = event.target instanceof Element ? event.target.closest("[data-node-id]") : null;
      if (target) return;
      scene.focus({ preventScroll: true });
      suppressClick = false;
      stopEdgePan();
      edgePanOffset = { x: 0, y: 0 };
      gestureRect = sceneGrid.getBoundingClientRect();
      pointers.set(event.pointerId, { x: event.clientX, y: event.clientY });
      resetFromCamera();
      if (pointers.size === 1) {
        startPoint = { x: event.clientX, y: event.clientY };
        startCentroid = null;
        startDistance = 0;
      } else if (pointers.size === 2) {
        startPoint = null;
        startCentroid = getCentroid();
        startDistance = getDistance();
      }
      try {
        sceneGrid.setPointerCapture(event.pointerId);
      } catch {
        // Pointer capture is not available in every embedded browser.
      }
    };
    const handlePointerMove = (event: PointerEvent) => {
      if (!pointers.has(event.pointerId) || !startCenter) return;
      pointers.set(event.pointerId, { x: event.clientX, y: event.clientY });
      const points = Array.from(pointers.values());

      if (points.length === 1 && startPoint) {
        const dx = points[0].x - startPoint.x;
        const dy = points[0].y - startPoint.y;
        if (Math.hypot(dx, dy) > 4) suppressClick = true;
        applySinglePointerCamera();
        if (suppressClick) scheduleEdgePan();
        return;
      }

      if (points.length >= 2 && startDistance > 0 && startCentroid) {
        const centroid = getCentroid();
        if (!centroid) return;
        const nextZoom = Math.min(Math.max(startZoom * (getDistance() / startDistance), 0.5), 2.4);
        sceneGrid.classList.add("is-gesture-active");
        suppressClick = true;
        viewport.applyCamera({
          center: pixelToAxialContinuous({
            x: startCenter.x - (centroid.x - startCentroid.x) / Math.max(nextZoom, 0.0001),
            y: startCenter.y - (centroid.y - startCentroid.y) / Math.max(nextZoom, 0.0001),
          }),
          zoom: nextZoom,
          viewportWidth: viewport.getCamera().viewportWidth,
          viewportHeight: viewport.getCamera().viewportHeight,
        });
      }
    };
    const handlePointerEnd = (event: PointerEvent) => {
      if (!pointers.has(event.pointerId)) return;
      pointers.delete(event.pointerId);
      try {
        if (sceneGrid.hasPointerCapture(event.pointerId)) sceneGrid.releasePointerCapture(event.pointerId);
      } catch {
        // Pointer capture may already have been released by the browser.
      }

      if (!pointers.size) {
        stopEdgePan();
        startCenter = null;
        startPoint = null;
        startCentroid = null;
        startDistance = 0;
        startZoom = 1;
        edgePanOffset = { x: 0, y: 0 };
        gestureRect = null;
        sceneGrid.classList.remove("is-gesture-active");
      } else if (pointers.size === 1) {
        stopEdgePan();
        const remaining = pointers.values().next().value;
        resetFromCamera();
        startPoint = remaining ? { ...remaining } : null;
        startCentroid = null;
        startDistance = 0;
        edgePanOffset = { x: 0, y: 0 };
        gestureRect = sceneGrid.getBoundingClientRect();
      }
    };
    const handleClick = (event: MouseEvent) => {
      if (!suppressClick) return;
      suppressClick = false;
      event.preventDefault();
      event.stopPropagation();
    };

    sceneGrid.addEventListener("pointerdown", handlePointerDown);
    sceneGrid.addEventListener("pointermove", handlePointerMove);
    sceneGrid.addEventListener("pointerup", handlePointerEnd);
    sceneGrid.addEventListener("pointercancel", handlePointerEnd);
    sceneGrid.addEventListener("click", handleClick, true);
    cleanups.push(() => sceneGrid.removeEventListener("pointerdown", handlePointerDown));
    cleanups.push(() => sceneGrid.removeEventListener("pointermove", handlePointerMove));
    cleanups.push(() => sceneGrid.removeEventListener("pointerup", handlePointerEnd));
    cleanups.push(() => sceneGrid.removeEventListener("pointercancel", handlePointerEnd));
    cleanups.push(() => sceneGrid.removeEventListener("click", handleClick, true));
    cleanups.push(stopEdgePan);
  }

  const handleSceneKeyDown = (event: KeyboardEvent) => {
    if (event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey) return;
    const target = event.target instanceof Element ? event.target : null;
    if (target?.closest("[data-node-id], button, input, select, textarea, a[href]")) return;

    const multiplier = event.shiftKey ? 2 : 1;
    const step = keyboardPanStep * multiplier;
    const offset = event.key === "ArrowLeft"
      ? { x: -step, y: 0 }
      : event.key === "ArrowRight"
        ? { x: step, y: 0 }
        : event.key === "ArrowUp"
          ? { x: 0, y: -step }
          : event.key === "ArrowDown"
            ? { x: 0, y: step }
            : null;

    if (!offset) return;
    event.preventDefault();
    viewport.panByScreen(offset.x, offset.y, false);
  };

  scene.addEventListener("keydown", handleSceneKeyDown);
  cleanups.push(() => scene.removeEventListener("keydown", handleSceneKeyDown));

  if (sceneGrid && enableSceneWheel) {
    const handleSceneWheel = (event: WheelEvent) => {
      event.preventDefault();
      viewport.zoomBy(event.deltaY > 0 ? -zoomStep : zoomStep);
    };
    sceneGrid.addEventListener("wheel", handleSceneWheel, { passive: false });
    cleanups.push(() => sceneGrid.removeEventListener("wheel", handleSceneWheel));
  }

  if (miniMap && interactiveMiniMap) {
    let interaction: { pointerId: number; moved: boolean; startX: number; startY: number } | null = null;
    const pointFromMiniMap = (event: PointerEvent) => {
      const rect = miniMap.getBoundingClientRect();
      const viewBox = miniMap.viewBox.baseVal;
      return {
        x: viewBox.x + ((event.clientX - rect.left) / Math.max(rect.width, 1)) * viewBox.width,
        y: viewBox.y + ((event.clientY - rect.top) / Math.max(rect.height, 1)) * viewBox.height,
      };
    };
    const handleMiniMapPointerDown = (event: PointerEvent) => {
      event.preventDefault();
      interaction = { pointerId: event.pointerId, moved: false, startX: event.clientX, startY: event.clientY };
      miniMap.setPointerCapture(event.pointerId);
      viewport.centerOnPoint(pointFromMiniMap(event), false);
    };
    const handleMiniMapPointerMove = (event: PointerEvent) => {
      if (!interaction || interaction.pointerId !== event.pointerId) return;
      if (Math.hypot(event.clientX - interaction.startX, event.clientY - interaction.startY) > 4) interaction.moved = true;
      viewport.centerOnPoint(pointFromMiniMap(event), false);
    };
    const handleMiniMapPointerEnd = (event: PointerEvent) => {
      if (!interaction || interaction.pointerId !== event.pointerId) return;
      if (!interaction.moved) viewport.centerOnPoint(pointFromMiniMap(event), !reducedMotion);
      try {
        if (miniMap.hasPointerCapture(event.pointerId)) miniMap.releasePointerCapture(event.pointerId);
      } catch {
        // Pointer capture may already have been released by the browser.
      }
      interaction = null;
    };
    const handleMiniMapWheel = (event: WheelEvent) => {
      event.preventDefault();
      viewport.zoomBy(event.deltaY > 0 ? -zoomStep : zoomStep);
    };

    miniMap.addEventListener("pointerdown", handleMiniMapPointerDown);
    miniMap.addEventListener("pointermove", handleMiniMapPointerMove);
    miniMap.addEventListener("pointerup", handleMiniMapPointerEnd);
    miniMap.addEventListener("pointercancel", handleMiniMapPointerEnd);
    miniMap.addEventListener("wheel", handleMiniMapWheel, { passive: false });
    cleanups.push(() => miniMap.removeEventListener("pointerdown", handleMiniMapPointerDown));
    cleanups.push(() => miniMap.removeEventListener("pointermove", handleMiniMapPointerMove));
    cleanups.push(() => miniMap.removeEventListener("pointerup", handleMiniMapPointerEnd));
    cleanups.push(() => miniMap.removeEventListener("pointercancel", handleMiniMapPointerEnd));
    cleanups.push(() => miniMap.removeEventListener("wheel", handleMiniMapWheel));
  }

  if (onMiniMapNodeSelect) {
    for (const node of miniNodes) {
      const handleNodeClick = (event: MouseEvent) => {
        event.stopPropagation();
        const entityId = node.getAttribute("data-topology-mini-node-id");
        if (!entityId) return;
        onMiniMapNodeSelect(entityId);
        select(entityId);
      };
      node.addEventListener("click", handleNodeClick);
      cleanups.push(() => node.removeEventListener("click", handleNodeClick));
    }
  }

  const resizeObserver = new ResizeObserver(() => viewport.updateViewport());
  for (const target of new Set(resizeTargets)) resizeObserver.observe(target);
  cleanups.push(() => resizeObserver.disconnect());

  if (fitOnInit && !restoredCamera) viewport.fit(false);
  select(activeId);
  onReady?.();

  const isDev = Boolean((import.meta as ImportMeta & { env?: { DEV?: boolean } }).env?.DEV);

  if (isDev) {
    const sceneId = ensureDeveloperSceneId(scene);
    const unregisterDeveloperCamera = registerDeveloperCamera(sceneId, {
      get: () => viewport.getCamera(),
      fit: () => viewport.fit(!reducedMotion),
      center: () => centerOnSelection(true),
      focus: (entityId) => viewport.ensureVisible(entityId, !reducedMotion),
      zoom(value) {
        viewport.applyCamera({
          ...viewport.getCamera(),
          zoom: value,
        });
      },
      reset: () => resetCamera(true),
    });
    cleanups.push(unregisterDeveloperCamera);
  }

  return {
    viewport,
    getSelectedId: () => activeId,
    select,
    syncRelationshipContext,
    setTopology,
    ensureVisible,
    centerOnSelection,
    resetCamera,
    destroy() {
      for (const cleanup of cleanups) cleanup();
      viewport.destroy();
    },
  };
}
